86	/****************************************************************************
87	 * Private Functions - Register Access Helpers
88	 ****************************************************************************/
89	
90	static inline uint32_t getreg32(uintptr_t addr)
91	{
92	  return *(volatile uint32_t *)addr;
93	}
94	
95	static inline void putreg32(uint32_t val, uintptr_t addr)
96	{
97	  *(volatile uint32_t *)addr = val;
98	}
99	
100	static void reset_assert(unsigned int id)
101	{
102	  unsigned int bank = id / 32;
103	  unsigned int bit = id % 32;
104	  uint32_t reg = getreg32(REG_RESET_BANK(bank));
105	
106	  putreg32(reg & ~(1u << bit), REG_RESET_BANK(bank));
107	}
108	
109	static void reset_deassert(unsigned int id)
110	{
111	  unsigned int bank = id / 32;
112	  unsigned int bit = id % 32;
113	  uint32_t reg = getreg32(REG_RESET_BANK(bank));
114	
115	  putreg32(reg | (1u << bit), REG_RESET_BANK(bank));
116	}
117	
118	static void clk_reset_deassert(unsigned int id)
119	{
120	  unsigned int bank = id / 32;
121	  unsigned int bit = id % 32;
122	  uintptr_t addr = SG2000_CLKGEN_BASE + bank * 4;
123	  uint32_t reg = getreg32(addr);
124	
125	  putreg32(reg | (1u << bit), addr);
126	}
