128	/****************************************************************************
129	 * Private Functions - Clock and Reset Control
130	 ****************************************************************************/
131	
132	static void gmac_clock_enable(void)
133	{
134	  uint32_t reg;
135	
136	  /* Enable GMAC0 clocks: clk_500m_eth0 + clk_axi4_eth0 */
137	
138	  reg = getreg32(REG_CLK_EN_0);
139	  reg |= CLK_EN_ETH0_500M | CLK_EN_ETH0_AXI4;
140	  putreg32(reg, REG_CLK_EN_0);
141	
142	  /* Deassert clock-domain resets used by the CVITEK clock-reset
143	   * controller.  Do not confuse these IDs with the main reset-controller
144	   * IDs at 0x03003000.
145	   */
146	
147	  clk_reset_deassert(CLK_RST_500M_ETH0);
148	  clk_reset_deassert(CLK_RST_AXI_ETH0);
149	
150	  /* Release the main reset-controller lines for GMAC and internal EPHY.
151	   * The Linux CVITEK reset driver deasserts by setting the corresponding
152	   * bit in the reset bank.
153	   */
154	
155	  reset_assert(RST_ETH0);
156	  reset_assert(RST_ETHPHY);
157	  reset_assert(RST_ETHPHYRST_APB);
158	  up_udelay(10);
159	  reset_deassert(RST_ETHPHYRST_APB);
160	  reset_deassert(RST_ETHPHY);
161	  reset_deassert(RST_ETH0);
162	  up_udelay(10);
163	
164	  syslog(LOG_INFO, "sg2000_eth: GMAC clocks enabled, CLK_EN_0=0x%08" PRIX32
165	         " RESET0=0x%08" PRIX32 " RESET3=0x%08" PRIX32 "\n",
166	         getreg32(REG_CLK_EN_0), getreg32(REG_RESET_BANK(0)),
167	         getreg32(REG_RESET_BANK(3)));
168	}
