170	/****************************************************************************
171	 * Private Functions - DMA Software Reset
172	 ****************************************************************************/
173	
174	static int dma_soft_reset(uintptr_t gmac_base)
175	{
176	  uint32_t val;
177	  int timeout = 100000;
178	
179	  val = getreg32(gmac_base + DMA_BUS_MODE);
180	  syslog(LOG_INFO, "sg2000_eth: DMA reset begin bus_mode=0x%08" PRIX32
181	         "\n", val);
182	  putreg32(val | DMA_SFT_RESET, gmac_base + DMA_BUS_MODE);
183	
184	  do
185	    {
186	      val = getreg32(gmac_base + DMA_BUS_MODE);
187	      if (!(val & DMA_SFT_RESET))
188	        {
189	          return 0;
190	        }
191	
192	      up_udelay(10);
193	    }
194	  while (--timeout > 0);
195	
196	  syslog(LOG_ERR, "sg2000_eth: DMA reset timeout bus_mode=0x%08" PRIX32
197	         " hw_feature0=0x%08" PRIX32 "\n",
198	         getreg32(gmac_base + DMA_BUS_MODE),
199	         getreg32(gmac_base + GMAC_HW_FEATURE0));
200	  return -1;
201	}
