350	static void ephy_hardware_reset(uintptr_t phy_base, uintptr_t phy_top)
351	{
352	  uint32_t apb_id1;
353	  uint32_t apb_id2;
354	
355	  ephy_led_pinmux();
356	
357	  /* Minimal EPHY init sequence, matches Linux bm_eth_reset_phy() in
358	   * dwmac-cvitek.c and U-Boot cv181x_ephy_id_init() in board.c.
359	   * This ONLY releases resets and programs the PHY ID — it does NOT
360	   * run the full analog tuning sequence.  The full tuning (which
361	   * accesses internal pages and starts auto-negotiation) must run
362	   * AFTER the MDIO interface is confirmed operational, just as
363	   * Linux does in cv182xa_phy_config_init() -> config_init callback.
364	   */
365	
366	  /* Select APB interface to access EPHY registers */
367	
368	  putreg32(0x0001, phy_top + 0x4);
369	
370	  /* Release shutdown */
371	
372	  putreg32(0x0900, phy_top);
373	
374	  /* Release dig_rst_n — enables MII register access via APB */
375	
376	  putreg32(0x0904, phy_top);
377	
378	  /* Switch to Page 5 for ANA init */
379	
380	  putreg32(0x0500, phy_base + 0x7c);
381	
382	  /* ANA_PD (power-down release) */
383	
384	  putreg32(0x0c00, phy_base + 0x40);
385	
386	  /* ANA_EN */
387	
388	  putreg32(0x0c7e, phy_base + 0x40);
389	  up_mdelay(1);
390	
391	  /* Release ana_rst_n */
392	
393	  putreg32(0x0906, phy_top);
394	  putreg32(0x0500, phy_base + 0x7c);
395	
396	  /* Program PHY ID into EPHY registers (so MDIO can discover it) */
397	
398	  putreg32(0x0043, phy_base + 0x08);  /* PHY_ID_HIGH */
399	  putreg32(0x5649, phy_base + 0x0c);  /* PHY_ID_LOW */
400	
401	  apb_id1 = getreg32(phy_base + 0x08) & 0xffff;
402	  apb_id2 = getreg32(phy_base + 0x0c) & 0xffff;
403	  syslog(LOG_INFO, "sg2000_eth: EPHY APB PHYID=0x%04" PRIX32
404	         "%04" PRIX32 "\n", apb_id1, apb_id2);
405	
406	  /* Switch control to MDIO (GMAC) so the DWMAC4 MDIO controller can
407	   * discover and communicate with the PHY.
408	   */
409	
410	  putreg32(0x0000, phy_top + 0x4);
411	  up_mdelay(10);
412	
413	  syslog(LOG_INFO, "sg2000_eth: EPHY init done top=0x%08" PRIX32
414	         " sel=0x%08" PRIX32 "\n",
415	         getreg32(phy_top), getreg32(phy_top + 0x4));
416	}
