418	/****************************************************************************
419	 * Name: ephy_full_tuning
420	 *
421	 * Description:
422	 *   Run the full CV182XA analog tuning sequence via APB, then switch back
423	 *   to MDIO control.  Matches Linux cv182xa_phy_config_init().
424	 *   MUST be called AFTER MDIO is confirmed operational, as it accesses
425	 *   internal pages and starts auto-negotiation which can interfere with
426	 *   MDIO if run before the MDIO interface is active.
427	 *
428	 ****************************************************************************/
429	
430	static void ephy_full_tuning(uintptr_t phy_base, uintptr_t phy_top)
431	{
432	  /* ephy_full_analog_init expects APB mode; caller ensures MDIO is working
433	   * before we switch to APB for tuning.
434	   */
435	
436	  putreg32(0x0001, phy_top + 0x4);
437	  ephy_full_analog_init(phy_base, phy_top);
438	
439	  /* ephy_full_analog_init ends with:
440	   *   page 0 + autoneg start (0x090e) + force full-duplex
441	   * Switch control back to MDIO so the GMAC can manage the PHY.
442	   */
443	
444	  putreg32(0x0000, phy_top + 0x4);
445	  up_mdelay(10);
446	
447	  syslog(LOG_INFO, "sg2000_eth: EPHY full tuning done, top=0x%08" PRIX32
448	         " sel=0x%08" PRIX32 "\n",
449	         getreg32(phy_top), getreg32(phy_top + 0x4));
450	}
