462	static uint16_t mdio_read_dwmac4(uintptr_t gmac_base, int phy_addr, int reg,
463	                                 bool *timedout)
464	{
465	  uint32_t cmd;
466	  uint32_t val;
467	  int timeout = 10000;
468	
469	  if (timedout != NULL)
470	    {
471	      *timedout = false;
472	    }
473	
474	  do
475	    {
476	      if (!(getreg32(gmac_base + GMAC_MDIO_ADDR) & GMAC_MDIO_BUSY))
477	        {
478	          break;
479	        }
480	
481	      up_udelay(1);
482	    }
483	  while (--timeout > 0);
484	
485	  if (timeout <= 0)
486	    {
487	      if (timedout != NULL)
488	        {
489	          *timedout = true;
490	        }
491	
492	      return 0xffff;
493	    }
494	
495	  putreg32(0, gmac_base + GMAC_MDIO_DATA);
496	
497	  cmd = (((uint32_t)phy_addr << GMAC_MDIO_PA_SHIFT) & GMAC_MDIO_PA_MASK) |
498	        (((uint32_t)reg << GMAC_MDIO_RDA_SHIFT) & GMAC_MDIO_RDA_MASK) |
499	        GMAC_MDIO_CR_250_300M | GMAC_MDIO_GOC_READ | GMAC_MDIO_BUSY;
500	  putreg32(cmd, gmac_base + GMAC_MDIO_ADDR);

500	  putreg32(cmd, gmac_base + GMAC_MDIO_ADDR);
501	
502	  timeout = 10000;
503	  do
504	    {
505	      val = getreg32(gmac_base + GMAC_MDIO_ADDR);
506	      if (!(val & GMAC_MDIO_BUSY))
507	        {
508	          return getreg32(gmac_base + GMAC_MDIO_DATA) & 0xffff;
509	        }
510	
511	      up_udelay(1);
512	    }
513	  while (--timeout > 0);
514	
515	  if (timedout != NULL)
516	    {
517	      *timedout = true;
518	    }
519	
520	  return 0xffff;
521	}
