579	      *timedout = true;
580	    }
581	
582	  return 0xffff;
583	}
584	
585	static uint16_t mdio_read_status(uintptr_t gmac_base, int phy_addr, int reg,
586	                                 bool *timedout)
587	{
588	  if (g_mdio_model == SG2000_MDIO_TRM_LEGACY)
589	    {
590	      return mdio_read_trm_legacy(gmac_base, phy_addr, reg, timedout);
591	    }
592	
593	  return mdio_read_dwmac4(gmac_base, phy_addr, reg, timedout);
594	}
595	
596	static uint16_t mdio_read(uintptr_t gmac_base, int phy_addr, int reg)
597	{
598	  return mdio_read_status(gmac_base, phy_addr, reg, NULL);
599	}
