625	static bool mdio_model_reads_phy_id(uintptr_t gmac_base,
626	                                    enum sg2000_mdio_model_e model,
627	                                    uint32_t *phy_id)
628	{
629	  bool to1;
630	  bool to2;
631	  uint16_t id1;
632	  uint16_t id2;
633	  enum sg2000_mdio_model_e saved = g_mdio_model;
634	
635	  g_mdio_model = model;
636	  id1 = mdio_read_status(gmac_base, 0, 2, &to1);
637	  id2 = mdio_read_status(gmac_base, 0, 3, &to2);
638	  g_mdio_model = saved;
639	
640	  *phy_id = ((uint32_t)id1 << 16) | id2;
641	  syslog(LOG_INFO, "sg2000_eth: MDIO probe %s id=0x%08" PRIX32
642	         " timeout=%d/%d\n", mdio_model_name(model), *phy_id,
643	         to1 ? 1 : 0, to2 ? 1 : 0);
644	
645	  return *phy_id == CVITEK_PHY_ID;
646	}
