651	
652	  mdio_diag_dump(gmac_base);
653	
654	  if (mdio_model_reads_phy_id(gmac_base, SG2000_MDIO_DWMAC4, &phy_id))
655	    {
656	      g_mdio_model = SG2000_MDIO_DWMAC4;
657	      syslog(LOG_INFO, "sg2000_eth: selected MDIO model %s\n",
658	             mdio_model_name(g_mdio_model));
