674	static void mdio_write_dwmac4(uintptr_t gmac_base, int phy_addr, int reg,
675	                              uint16_t data)
676	{
677	  uint32_t cmd;
678	  int timeout = 10000;
679	
680	  putreg32(data, gmac_base + GMAC_MDIO_DATA);
681	  cmd = (((uint32_t)phy_addr << GMAC_MDIO_PA_SHIFT) & GMAC_MDIO_PA_MASK) |
682	        (((uint32_t)reg << GMAC_MDIO_RDA_SHIFT) & GMAC_MDIO_RDA_MASK) |
683	        GMAC_MDIO_CR_250_300M | GMAC_MDIO_GOC_WRITE | GMAC_MDIO_BUSY;
684	  putreg32(cmd, gmac_base + GMAC_MDIO_ADDR);
685	
686	  do
687	    {
688	      if (!(getreg32(gmac_base + GMAC_MDIO_ADDR) & GMAC_MDIO_BUSY))
689	        {
690	          break;
691	        }
692	
693	      up_udelay(1);
694	    }
695	  while (--timeout > 0);
696	}
697	
698	static void mdio_write_trm_legacy(uintptr_t gmac_base, int phy_addr, int reg,
699	                                  uint16_t data)
700	{
701	  uint32_t cmd;
702	  int timeout = 10000;
703	  uintptr_t base = gmac_base;
704	
705	  putreg32(data, base + LEGACY_GMAC_MDIO_DATA);
706	  cmd = (((uint32_t)phy_addr & 0x1f) << LEGACY_GMAC_MDIO_PHY_SHIFT) |
707	        (((uint32_t)reg & 0x1f) << LEGACY_GMAC_MDIO_REG_SHIFT) |
708	        LEGACY_GMAC_MDIO_WRITE | LEGACY_GMAC_MDIO_BUSY;
709	  putreg32(cmd, base + LEGACY_GMAC_MDIO_ADDR);
710	
711	  do
712	    {
713	      if (!(getreg32(base + LEGACY_GMAC_MDIO_ADDR) & LEGACY_GMAC_MDIO_BUSY))
714	        {
715	          break;
716	        }
717	
718	      up_udelay(1);
719	    }
720	  while (--timeout > 0);
721	}
722	
723	static void mdio_write(uintptr_t gmac_base, int phy_addr, int reg,
724	                       uint16_t data)
725	{
726	  if (g_mdio_model == SG2000_MDIO_TRM_LEGACY)
727	    {
728	      mdio_write_trm_legacy(gmac_base, phy_addr, reg, data);
729	      return;
730	    }
731	
732	  mdio_write_dwmac4(gmac_base, phy_addr, reg, data);
733	}
