735	/****************************************************************************
736	 * Private Functions - PHY Configuration
737	 ****************************************************************************/
738	
739	static int phy_config_init(struct sg2000_eth_priv_s *priv)
740	{
741	  uint16_t bmsr;
742	  uint16_t bmcr;
743	  uint16_t anlpar;
744	  int timeout;
745	  uint16_t id1 = mdio_read(priv->gmac_base, 0, 2);
746	  uint16_t id2 = mdio_read(priv->gmac_base, 0, 3);
747	  uint32_t phy_id = (id1 << 16) | id2;
748	
749	  syslog(LOG_INFO, "sg2000_eth: PHY ID=0x%08" PRIX32
750	         " expect=0x00435649\n", phy_id);
751	
752	  if (phy_id == 0xffffffff)
753	    {
754	      syslog(LOG_ERR, "sg2000_eth: PHY not responding\n");
755	      return -1;
756	    }
757	
758	  if (phy_id != CVITEK_PHY_ID)
759	    {
760	      syslog(LOG_WARNING, "sg2000_eth: unexpected PHY ID 0x%08" PRIX32
761	             "\n", phy_id);
762	    }
763	
764	  priv->speed = 100;
765	  priv->duplex = 1;
766	
767	  mdio_write(priv->gmac_base, 0, 0, 0x8000);
768	  up_mdelay(10);
769	
770	  timeout = 100;
771	  do
772	    {
773	      bmcr = mdio_read(priv->gmac_base, 0, 0);
774	      if (!(bmcr & 0x8000))
775	        {
776	          break;
777	        }
778	
779	      up_mdelay(1);
780	    }
781	  while (--timeout > 0);
782	
783	  syslog(LOG_INFO, "sg2000_eth: PHY reset done, BMCR=0x%04X\n", bmcr);
784	
785	  mdio_write(priv->gmac_base, 0, 4, 0x01e1);
786	
787	  bmcr = mdio_read(priv->gmac_base, 0, 0);
788	  mdio_write(priv->gmac_base, 0, 0, bmcr | 0x1200);
789	  syslog(LOG_INFO, "sg2000_eth: autoneg start, BMCR=0x%04X\n",
790	         bmcr | 0x1200);
791	
792	  timeout = 50;
793	  do
794	    {
795	      (void)mdio_read(priv->gmac_base, 0, 1);
796	      bmsr = mdio_read(priv->gmac_base, 0, 1);
797	      if ((bmsr & 0x0004) != 0)
798	        {
799	          break;
800	        }
801	
802	      up_mdelay(100);
803	    }
804	  while (--timeout > 0);
805	
806	  if ((bmsr & 0x0004) == 0)
807	    {
808	      syslog(LOG_WARNING, "sg2000_eth: PHY link down, BMSR=0x%04X\n",
809	             bmsr);
810	      priv->link_up = 0;
811	      return OK;
812	    }
813	
814	  anlpar = mdio_read(priv->gmac_base, 0, 5);
815	  syslog(LOG_INFO, "sg2000_eth: PHY link detected, BMSR=0x%04X "
816	         "ANLPAR=0x%04X\n", bmsr, anlpar);
817	
818	  if ((anlpar & 0x0100) != 0)
819	    {
820	      priv->speed = 100;
821	      priv->duplex = 1;
822	    }
823	  else if ((anlpar & 0x0080) != 0)
824	    {
825	      priv->speed = 100;
826	      priv->duplex = 0;
827	    }
828	  else if ((anlpar & 0x0040) != 0)
829	    {
830	      priv->speed = 10;
831	      priv->duplex = 1;
832	    }
833	  else
834	    {
835	      priv->speed = 10;
836	      priv->duplex = 0;
837	    }
838	
839	  priv->link_up = 1;
840	
841	  return 0;
842	}
