844	/****************************************************************************
845	 * Private Functions - DMA Descriptor Management
846	 ****************************************************************************/
847	
848	static int alloc_dma(struct sg2000_eth_priv_s *priv)
849	{
850	  int i;
851	
852	  priv->tx_desc = kmm_memalign(16, TX_RING_SIZE *
853	                                sizeof(struct sg2000_dma_desc_s));
854	  priv->rx_desc = kmm_memalign(16, RX_RING_SIZE *
855	                                sizeof(struct sg2000_dma_desc_s));
856	
857	  if (!priv->tx_desc || !priv->rx_desc)
858	    {
859	      return -ENOMEM;
860	    }
861	
862	  memset(priv->tx_desc, 0, TX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
863	  memset(priv->rx_desc, 0, RX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
864	
865	  /* For MMU-less or identity-mapped platforms, virtual address = physical.
866	   * TODO: For strict MMU kernel builds, use mm_virt_to_phys().
867	   */
868	
869	  priv->tx_desc_phys = (uint32_t)(uintptr_t)priv->tx_desc;
870	  priv->rx_desc_phys = (uint32_t)(uintptr_t)priv->rx_desc;
871	
872	  for (i = 0; i < TX_RING_SIZE; i++)
873	    {
874	      priv->tx_buf[i] = kmm_memalign(4, TX_BUF_SIZE);
875	      if (!priv->tx_buf[i])
876	        {
877	          return -ENOMEM;
878	        }
879	
880	      priv->tx_pkt[i] = NULL;
881	    }
882	
883	  for (i = 0; i < RX_RING_SIZE; i++)
884	    {
885	      priv->rx_buf[i] = kmm_memalign(4, RX_BUF_SIZE);
886	      if (!priv->rx_buf[i])
887	        {
888	          return -ENOMEM;
889	        }
890	    }
891	
892	  return 0;
893	}
894	
895	static void init_desc_and_dma(struct sg2000_eth_priv_s *priv)
896	{
897	  uintptr_t base = priv->gmac_base;
898	  uintptr_t dma = base + DMA_CHAN_BASE;
899	  int i;
900	
901	  /* Initialize TX descriptors */
902	
903	  for (i = 0; i < TX_RING_SIZE; i++)
904	    {
905	      priv->tx_desc[i].des0 = 0;
906	      priv->tx_desc[i].des2 = (uint32_t)(uintptr_t)priv->tx_buf[i];
907	      priv->tx_pkt[i] = NULL;
908	    }
909	
910	  /* Initialize RX descriptors: set OWN=1 (DMA owns them, can write) */
911	
912	  for (i = 0; i < RX_RING_SIZE; i++)
913	    {
914	      priv->rx_desc[i].des0 = DESC_OWN;
915	      priv->rx_desc[i].des1 = RX_BUF_SIZE;
916	      priv->rx_desc[i].des2 = (uint32_t)(uintptr_t)priv->rx_buf[i];
917	    }
918	
919	  priv->tx_cur = 0;
920	  priv->tx_dirty = 0;
921	  priv->rx_cur = 0;
922	
923	  /* Program DMA registers */
924	
925	  putreg32(DMA_SYS_DEFAULT, base + DMA_SYS_BUS_MODE);
926	  putreg32(TX_RING_SIZE - 1, dma + DMA_CHAN_TX_RING_LEN);
927	  putreg32(RX_RING_SIZE - 1, dma + DMA_CHAN_RX_RING_LEN);
928	  putreg32(priv->tx_desc_phys, dma + DMA_CHAN_TX_BASE_ADDR);
929	  putreg32(priv->rx_desc_phys, dma + DMA_CHAN_RX_BASE_ADDR);
930	  putreg32(DMA_INTR_DEFAULT_MASK, dma + DMA_CHAN_INTR_ENA);
931	}
