933	/****************************************************************************
934	 * Private Functions - MAC and DMA Control
935	 ****************************************************************************/
936	
937	static void set_mac_addr(uintptr_t gmac_base, const uint8_t *mac)
938	{
939	  uint32_t hi;
940	  uint32_t lo;
941	
942	  hi = (mac[5] << 8) | mac[4] | GMAC_HI_REG_AE;
943	  lo = (mac[3] << 24) | (mac[2] << 16) | (mac[1] << 8) | mac[0];
944	
945	  putreg32(hi, gmac_base + GMAC_ADDR_HIGH(0));
946	  putreg32(lo, gmac_base + GMAC_ADDR_LOW(0));
947	}
948	
949	static void start_mac_and_dma(struct sg2000_eth_priv_s *priv)
950	{
951	  uintptr_t gmac_base = priv->gmac_base;
952	  uintptr_t dma = gmac_base + DMA_CHAN_BASE;
953	  uint32_t v;
954	
955	  /* Configure MAC based on PHY negotiation results */
956	
957	  v = GMAC_CORE_INIT;
958	  if (priv->speed == 100)
959	    {
960	      v |= GMAC_CONFIG_FES;   /* 100M */
961	    }
962	
963	  if (priv->duplex)
964	    {
965	      v |= GMAC_CONFIG_DM;    /* Full duplex */
966	    }
967	
968	  putreg32(v, gmac_base + GMAC_CONFIG);
969	
970	  /* Packet filter: pass multicast + broadcast + unicast to us */
971	
972	  putreg32(GMAC_FILTER_HMC | GMAC_FILTER_PM | GMAC_FILTER_PR,
973	           gmac_base + GMAC_PACKET_FILTER);
974	
975	  /* Enable MAC interrupts */
976	
977	  putreg32(GMAC_INT_DEFAULT, gmac_base + GMAC_INT_EN);
978	
979	  /* Enable MAC TX and RX */
980	
981	  v = getreg32(gmac_base + GMAC_CONFIG);
982	  putreg32(v | GMAC_CONFIG_TE | GMAC_CONFIG_RE, gmac_base + GMAC_CONFIG);
983	
984	  /* Start TX DMA */
985	
986	  v = getreg32(dma + DMA_CHAN_TX_CONTROL);
987	  putreg32(v | DMA_TX_ST, dma + DMA_CHAN_TX_CONTROL);
988	
989	  /* Start RX DMA */
990	
991	  v = getreg32(dma + DMA_CHAN_RX_CONTROL);
992	  putreg32(v | DMA_RX_SR, dma + DMA_CHAN_RX_CONTROL);
993	}
