996	 * Private Functions - Doorbell Helpers
997	 ****************************************************************************/
998	
999	static void tx_doorbell(struct sg2000_eth_priv_s *priv)

999	static void tx_doorbell(struct sg2000_eth_priv_s *priv)
1000	{
1001	  uint32_t tail = priv->tx_desc_phys +
1002	                  priv->tx_cur * sizeof(struct sg2000_dma_desc_s);
1003	
1004	  putreg32(tail, priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_END_ADDR);
1005	}
1006	
1007	static void rx_doorbell(struct sg2000_eth_priv_s *priv)
1008	{
1009	  uint32_t tail = priv->rx_desc_phys +
1010	                  priv->rx_cur * sizeof(struct sg2000_dma_desc_s);
1011	
1012	  putreg32(tail, priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_END_ADDR);
1013	}
