1015	/****************************************************************************
1016	 * Private Functions - Hardware Transmit
1017	 ****************************************************************************/
1018	
1019	static int hw_transmit(struct sg2000_eth_priv_s *priv,
1020	                       const uint8_t *data, int len)
1021	{
1022	  unsigned int idx = priv->tx_cur;
1023	  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
1024	  irqstate_t flags;
1025	
1026	  /* Check if the ring is full */
1027	
1028	  if (desc->des0 & DESC_OWN)
1029	    {
1030	      return -EBUSY;
1031	    }
1032	
1033	  /* Copy data to DMA TX buffer */
1034	
1035	  memcpy(priv->tx_buf[idx], data, len);
1036	
1037	  desc->des2 = (uint32_t)(uintptr_t)priv->tx_buf[idx];
1038	  desc->des1 = len;
1039	
1040	  /* OWN | First Segment | Last Segment | Interrupt on Completion */
1041	
1042	  desc->des0 = DESC_OWN | TX_DESC_FS | TX_DESC_LS | TX_DESC_IC |
1043	               (len & RX_DESC_FL_MASK);
1044	
1045	  flags = up_irq_save();
1046	  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);
1047	
1048	  /* Memory barrier: ensure descriptor is visible to DMA engine */
1049	
1050	  __asm__ volatile ("fence w,w" ::: "memory");
1051	
1052	  tx_doorbell(priv);
1053	  up_irq_restore(flags);
1054	
1055	  return 0;
1056	}
1057	
1058	/****************************************************************************
1059	 * Private Functions - TX Cleanup (called from ISR on TX complete)
1060	 ****************************************************************************/
1061	
1062	static void tx_cleanup(struct sg2000_eth_priv_s *priv)
1063	{
1064	  irqstate_t flags = up_irq_save();
1065	
1066	  while (priv->tx_dirty != priv->tx_cur)
1067	    {
1068	      struct sg2000_dma_desc_s *desc = &priv->tx_desc[priv->tx_dirty];
1069	
1070	      if (desc->des0 & DESC_OWN)
1071	        {
1072	          /* Still owned by DMA, stop */
1073	
1074	          break;
1075	        }
1076	
1077	      /* Check for TX errors */
1078	
1079	      if (desc->des0 & TX_DESC_ES)
1080	        {
1081	          nerr("ERROR: TX error, status=0x%08" PRIX32 "\n", desc->des0);
1082	        }
1083	
1084	      /* Free the netpkt if we have one tracked for this slot */
1085	
1086	      if (priv->tx_pkt[priv->tx_dirty] != NULL)
1087	        {
1088	          netpkt_free(&priv->dev, priv->tx_pkt[priv->tx_dirty], NETPKT_TX);
1089	          priv->tx_pkt[priv->tx_dirty] = NULL;
1090	
1091	          /* Notify upper half that TX is done */
1092	
1093	          netdev_lower_txdone(&priv->dev);
1094	        }
1095	
1096	      /* Move to next descriptor */
1097	
1098	      priv->tx_dirty = (priv->tx_dirty + 1) & (TX_RING_SIZE - 1);
1099	    }
1100	
1101	  up_irq_restore(flags);
1102	}
1103	
1104	/****************************************************************************
1105	 * Private Functions - ISR
1106	 ****************************************************************************/
1107	
1108	static int sg2000_eth_isr(int irq, void *context, void *arg)
1109	{
1110	  struct sg2000_eth_priv_s *priv = (struct sg2000_eth_priv_s *)arg;
1111	  uintptr_t base = priv->gmac_base;
1112	  uintptr_t dma = base + DMA_CHAN_BASE;
1113	  uint32_t status;
1114	  uint32_t intr_en;
1115	  uint32_t mac;
1116	
1117	  /* Clear MAC interrupts */
1118	
1119	  mac = getreg32(base + GMAC_INT_STATUS);
1120	  if (mac)
1121	    {
1122	      putreg32(mac, base + GMAC_INT_STATUS);
1123	    }
1124	
1125	  /* Read DMA channel status (only enabled interrupts) */
1126	
1127	  intr_en = getreg32(dma + DMA_CHAN_INTR_ENA);
1128	  status = getreg32(dma + DMA_CHAN_STATUS) & intr_en;
1129	
1130	  if (!status)
1131	    {
1132	      return OK;
1133	    }
1134	
1135	  /* Write-1-to-clear the status bits */
1136	
1137	  putreg32(status, dma + DMA_CHAN_STATUS);
1138	
1139	  if (status & DMA_STATUS_NIS)
1140	    {
1141	      /* Normal interrupt */
1142	
1143	      if (status & DMA_STATUS_RI)
1144	        {
1145	          /* RX complete: notify upper half that packets are ready.
1146	           * The upper half will call our receive() callback to get them.
1147	           */
1148	
1149	          netdev_lower_rxready(&priv->dev);
1150	        }
1151	
1152	      if (status & DMA_STATUS_TI)
1153	        {
1154	          /* TX complete: cleanup descriptors and notify upper half */
1155	
1156	          tx_cleanup(priv);
1157	        }
1158	    }
1159	
1160	  if (status & DMA_STATUS_AIS)
1161	    {
1162	      /* Abnormal interrupt */
1163	
1164	      nerr("ERROR: DMA Abnormal: 0x%08" PRIX32 "\n", status);
1165	
1166	      if (status & DMA_STATUS_RBU)
1167	        {
1168	          nerr("ERROR: RX Buffer Unavailable\n");
1169	        }
1170	
1171	      if (status & DMA_STATUS_TPS)
1172	        {
1173	          nerr("ERROR: TX Process Stopped\n");
1174	        }
1175	
1176	      if (status & DMA_STATUS_FBE)
1177	        {
1178	          nerr("ERROR: Fatal Bus Error\n");
1179	        }
1180	    }
1181	
1182	  return OK;
1183	}
1184	
1185	/****************************************************************************
1186	 * Name: netdriver_ifup
1187	 *
1188	 * Description:
1189	 *   OpenVela netdev_ops_s ifup callback.  Starts the network device.
1190	 *
1191	 ****************************************************************************/
1192	
1193	static int netdriver_ifup(FAR struct netdev_lowerhalf_s *dev)
1194	{
1195	  FAR struct sg2000_eth_priv_s *priv =
1196	      (FAR struct sg2000_eth_priv_s *)dev;
1197	  int ret;
1198	
1199	  syslog(LOG_INFO, "sg2000_eth: ifup begin\n");
1200	
1201	  /* Ensure GMAC clocks and resets are configured */
1202	
1203	  gmac_clock_enable();
1204	
1205	  /* Set MAC core init (includes PS=MII mode) before PHY/MDIO operations. */
1206	
1207	  putreg32(GMAC_CORE_INIT, priv->gmac_base + GMAC_CONFIG);
1208	
1209	  ephy_hardware_reset(priv->phy_base, priv->phy_top);
1210	  up_mdelay(10);
1211	
1212	  ret = mdio_select_model(priv->gmac_base);
1213	  if (ret < 0)
1214	    {
1215	      nerr("ERROR: MDIO model probe failed before PHY init: %d\n", ret);
1216	      return ret;
1217	    }
1218	
1219	  syslog(LOG_INFO, "sg2000_eth: MDIO before PHY init addr=0x%08" PRIX32
1220	         " data=0x%08" PRIX32 "\n",
1221	         getreg32(priv->gmac_base + GMAC_MDIO_ADDR),
1222	         getreg32(priv->gmac_base + GMAC_MDIO_DATA));
1223	
1224	  ephy_full_tuning(priv->phy_base, priv->phy_top);
1225	
1226	  ret = phy_config_init(priv);
1227	  if (ret < 0)
1228	    {
1229	      nerr("ERROR: PHY init failed: %d\n", ret);
1230	      return ret;
1231	    }
1232	
1233	  ret = dma_soft_reset(priv->gmac_base);
1234	  if (ret < 0)
1235	    {
1236	      syslog(LOG_ERR, "sg2000_eth: DMA reset failed after PHY/MDIO "
1237	             "diagnostics: %d\n", ret);
1238	      return ret;
1239	    }
1240	
1241	  if (priv->tx_desc == NULL || priv->rx_desc == NULL)
1242	    {
1243	      ret = alloc_dma(priv);
1244	      if (ret < 0)
1245	        {
1246	          nerr("ERROR: alloc_dma failed: %d\n", ret);
1247	          return ret;
1248	        }
1249	    }
1250	
1251	  init_desc_and_dma(priv);
1252	  set_mac_addr(priv->gmac_base, priv->mac_addr);
1253	  start_mac_and_dma(priv);
1254	  rx_doorbell(priv);
1255	
1256	  up_enable_irq(priv->irq);
1257	  netdev_lower_carrier_on(dev);
1258	
1259	  syslog(LOG_INFO, "sg2000_eth: ifup done, %d Mbps %s duplex\n",
1260	         priv->speed, priv->duplex ? "Full" : "Half");
1261	
1262	  return OK;
1263	}
1264	
1265	/****************************************************************************
1266	 * Name: netdriver_ifdown
1267	 *
1268	 * Description:
1269	 *   OpenVela netdev_ops_s ifdown callback.  Stops the network device.
1270	 *
1271	 ****************************************************************************/
1272	
1273	static int netdriver_ifdown(FAR struct netdev_lowerhalf_s *dev)
1274	{
1275	  FAR struct sg2000_eth_priv_s *priv =
1276	      (FAR struct sg2000_eth_priv_s *)dev;
1277	  uint32_t v;
1278	
1279	  up_disable_irq(priv->irq);
1280	
1281	  /* Stop TX DMA */
1282	
1283	  v = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_CONTROL);
1284	  putreg32(v & ~DMA_TX_ST,
1285	           priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_TX_CONTROL);
1286	
1287	  /* Stop RX DMA */
1288	
1289	  v = getreg32(priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL);
1290	  putreg32(v & ~DMA_RX_SR,
1291	           priv->gmac_base + DMA_CHAN_BASE + DMA_CHAN_RX_CONTROL);
1292	
1293	  /* Disable MAC TX/RX */
1294	
1295	  v = getreg32(priv->gmac_base + GMAC_CONFIG);
1296	  putreg32(v & ~(GMAC_CONFIG_TE | GMAC_CONFIG_RE),
1297	           priv->gmac_base + GMAC_CONFIG);
1298	
1299	  netdev_lower_carrier_off(dev);
1300	
1301	  ninfo("netdriver_ifdown: interface down\n");
1302	
1303	  return OK;
1304	}
1305	
1306	/****************************************************************************
1307	 * Name: netdriver_transmit
1308	 *
1309	 * Description:
1310	 *   OpenVela netdev_ops_s transmit callback.  Sends a packet.
1311	 *   The driver takes ownership of the netpkt and MUST free it after TX
1312	 *   completion (or on error).
1313	 *
1314	 *   Returned Value:
1315	 *     OK on success (pkt queued for TX); negated errno on failure.
1316	 *
1317	 ****************************************************************************/
1318	
1319	static int netdriver_transmit(FAR struct netdev_lowerhalf_s *dev,
1320	                               FAR netpkt_t *pkt)
1321	{
1322	  FAR struct sg2000_eth_priv_s *priv =
1323	      (FAR struct sg2000_eth_priv_s *)dev;
1324	  unsigned int len = netpkt_getdatalen(dev, pkt);
1325	  uint8_t tmp_buf[SG2000_ETH_BUFSIZE];
1326	  const uint8_t *data;
1327	  int ret;
1328	
1329	  if (len > SG2000_ETH_BUFSIZE)
1330	    {
1331	      nerr("ERROR: TX packet too large: %u\n", len);
1332	      netpkt_free(dev, pkt, NETPKT_TX);
1333	      return -E2BIG;
1334	    }
1335	
1336	  /* Extract data from netpkt.  If fragmented, copy out; else use pointer. */
1337	
1338	  if (netpkt_is_fragmented(pkt))
1339	    {
1340	      netpkt_copyout(dev, tmp_buf, pkt, len, 0);
1341	      data = tmp_buf;
1342	    }
1343	  else
1344	    {
1345	      data = netpkt_getdata(dev, pkt);
1346	      if (!data)
1347	        {
1348	          nerr("ERROR: netpkt_getdata returned NULL\n");
1349	          netpkt_free(dev, pkt, NETPKT_TX);
1350	          return -EINVAL;
1351	        }
1352	    }
1353	
1354	  /* Send via DMA */
1355	
1356	  ret = hw_transmit(priv, data, len);
1357	  if (ret < 0)
1358	    {
1359	      nerr("ERROR: hw_transmit failed: %d\n", ret);
1360	      netpkt_free(dev, pkt, NETPKT_TX);
1361	      return ret;
1362	    }
1363	
1364	  /* Track this packet: store it so tx_cleanup can free it after DMA done.
1365	   * The tx_cur was already advanced by hw_transmit, so use (tx_cur - 1).
1366	   */
1367	
1368	  {
1369	    irqstate_t flags = up_irq_save();
1370	    unsigned int slot = (priv->tx_cur - 1) & (TX_RING_SIZE - 1);
1371	
1372	    priv->tx_pkt[slot] = pkt;
1373	    up_irq_restore(flags);
1374	  }
1375	
1376	  return OK;
1377	}
1378	
1379	/****************************************************************************
1380	 * Name: netdriver_receive
1381	 *
1382	 * Description:
1383	 *   OpenVela netdev_ops_s receive callback.  Called by upper half when
1384	 *   netdev_lower_rxready() was signaled.  Returns one received packet, or
1385	 *   NULL if no more packets are available.
1386	 *
1387	 *   Returned Value:
1388	 *     A netpkt_t * containing the received packet, or NULL.
1389	 *
1390	 ****************************************************************************/
1391	
1392	static FAR netpkt_t *netdriver_receive(FAR struct netdev_lowerhalf_s *dev)
1393	{
1394	  FAR struct sg2000_eth_priv_s *priv =
1395	      (FAR struct sg2000_eth_priv_s *)dev;
1396	  FAR netpkt_t *pkt = NULL;
1397	  struct sg2000_dma_desc_s *desc;
1398	  uint32_t status;
1399	  int frame_len;
1400	  int ret;
1401	
1402	  /* Check if there is a completed RX descriptor */
1403	
1404	  desc = &priv->rx_desc[priv->rx_cur];
1405	  if (desc->des0 & DESC_OWN)
1406	    {
1407	      /* DMA still owns it, no packet ready yet.
1408	       * This can happen if rxready was signaled for a previous packet
1409	       * that was already consumed, or in edge cases.
1410	       */
1411	
1412	      return NULL;
1413	    }
1414	
1415	  status = desc->des0;
1416	
1417	  /* Check for errors */
1418	
1419	  if (status & RX_DESC_ES)
1420	    {
1421	      nerr("ERROR: RX error, status=0x%08" PRIX32 "\n", status);
1422	      goto refill;
1423	    }
1424	
1425	  /* Get frame length (includes FCS which we strip) */
1426	
1427	  frame_len = ((status >> RX_DESC_FL_SHIFT) & RX_DESC_FL_MASK) - ETH_FCSSLEN;
1428	
1429	  if (frame_len <= 0 || frame_len > CONFIG_NET_ETH_PKTSIZE)
1430	    {
1431	      nwarn("WARNING: Invalid RX frame length: %d\n", frame_len);
1432	      goto refill;
1433	    }
1434	
1435	  /* Allocate a netpkt for the received data */
1436	
1437	  pkt = netpkt_alloc(dev, NETPKT_RX);
1438	  if (!pkt)
1439	    {
1440	      nerr("ERROR: netpkt_alloc failed\n");
1441	      goto refill;
1442	    }
1443	
1444	  /* Copy data from DMA RX buffer into the netpkt */
1445	
1446	  ret = netpkt_copyin(dev, pkt, priv->rx_buf[priv->rx_cur], frame_len, 0);
1447	  if (ret < 0)
1448	    {
1449	      nerr("ERROR: netpkt_copyin failed: %d\n", ret);
1450	      netpkt_free(dev, pkt, NETPKT_RX);
1451	      goto refill;
1452	    }
1453	
1454	  ninfo("RX packet: %d bytes\n", frame_len);
1455	
1456	refill:
1457	  /* Return the descriptor to DMA (set OWN=1) */
1458	
1459	  desc->des0 = DESC_OWN;
1460	  desc->des1 = RX_BUF_SIZE;
1461	
1462	  priv->rx_cur = (priv->rx_cur + 1) & (RX_RING_SIZE - 1);
1463	  rx_doorbell(priv);
1464	
1465	  return pkt;
1466	}
1467	
1468	/****************************************************************************
1469	 * Private Data - Operations Structure
1470	 *
1471	 * The netdev_ops_s maps our callbacks to the OpenVela lowerhalf API.
1472	 ****************************************************************************/
1473	
1474	static const struct netdev_ops_s g_ops =
1475	{
1476	  netdriver_ifup,     /* ifup */
1477	  netdriver_ifdown,   /* ifdown */
1478	  netdriver_transmit, /* transmit */
1479	  netdriver_receive   /* receive */
1480	  /* addmac, rmmac, ioctl, reclaim are not implemented for this simple
1481	   * Ethernet MAC driver.  They are only required for Wi-Fi or advanced
1482	   * filtering scenarios.
1483	   */
1484	};
1485	
1486	/****************************************************************************
1487	 * Public Functions
1488	 ****************************************************************************/
1489	
1490	/****************************************************************************
1491	 * Name: sg2000_eth_initialize
1492	 *
1493	 * Description:
1494	 *   Initialize the SG2000 Ethernet driver and register it with the OpenVela
1495	 *   network stack as a netdev_lowerhalf_s device.
1496	 *
1497	 *   Called from board_late_initialize() during system bringup.
1498	 *
1499	 ****************************************************************************/
1500	
1501	int sg2000_eth_initialize(void)
1502	{
1503	  FAR struct sg2000_eth_priv_s *priv = &g_eth_priv;
1504	  FAR struct netdev_lowerhalf_s *dev = &priv->dev;
1505	  int ret;
1506	
1507	  if (g_eth_initialized)
1508	    {
1509	      ninfo("SG2000 Ethernet driver already initialized\n");
1510	      return OK;
1511	    }
1512	
1513	  memset(priv, 0, sizeof(*priv));
1514	  priv->gmac_base = SG2000_GMAC_BASE;
1515	  priv->phy_base = SG2000_EPHY_BASE;
1516	  priv->phy_top = SG2000_EPHY_TOP;
1517	
1518	  /* Set a test MAC address (should be replaced with eFuse/OTP value) */
1519	
1520	  priv->mac_addr[0] = 0x02;
1521	  priv->mac_addr[1] = 0x00;
1522	  priv->mac_addr[2] = 0x00;
1523	  priv->mac_addr[3] = 0x00;
1524	  priv->mac_addr[4] = 0x00;
1525	  priv->mac_addr[5] = 0x01;
1526	
1527	  memcpy(dev->netdev.d_mac.ether.ether_addr_octet, priv->mac_addr,
1528	         IFHWADDRLEN);
1529	
1530	  dev->quota[NETPKT_TX] = TX_RING_SIZE / 2;
1531	  dev->quota[NETPKT_RX] = RX_RING_SIZE / 2;
1532	  dev->ops              = &g_ops;
1533	
1534	  priv->irq = SG2000_IRQ_GMAC;
1535	
1536	  ret = netdev_lower_register(dev, NET_LL_ETHERNET);
1537	  if (ret < 0)
1538	    {
1539	      nerr("ERROR: netdev_lower_register failed: %d\n", ret);
1540	      return ret;
1541	    }
1542	
1543	  netdev_lower_carrier_off(dev);
1544	  g_eth_initialized = true;
1545	  ninfo("SG2000 Ethernet driver registered as eth0 (lowerhalf)\n");
1546	
1547	  gmac_clock_enable();
1548	
1549	  ret = irq_attach(priv->irq, sg2000_eth_isr, priv);
1550	  if (ret < 0)
1551	    {
1552	      nerr("ERROR: irq_attach failed: %d\n", ret);
1553	      return OK;
1554	    }
1555	
1556	  up_enable_irq(priv->irq);
1557	  ninfo("IRQ %d enabled\n", priv->irq);
1558	
1559	  return OK;
1560	}
1561	
1562	/****************************************************************************
1563	 * Name: riscv_netinitialize
1564	 *
1565	 * Description:
1566	 *   Arch-level network initialization called from up_initialize().
1567	 *   Initializes the SG2000 Ethernet driver.
1568	 *
1569	 ****************************************************************************/
1570	
1571	void riscv_netinitialize(void)
1572	{
1573	  /* SG2000 Ethernet needs board-level bringup ordering.  It is initialized
1574	   * from board_late_initialize() after the core OS initialization path.
