enum sg2000_mdio_model_e
{
  SG2000_MDIO_DWMAC4 = 0,
  SG2000_MDIO_TRM_LEGACY,
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct sg2000_eth_priv_s g_eth_priv;
static bool g_eth_initialized;
static enum sg2000_mdio_model_e g_mdio_model = SG2000_MDIO_DWMAC4;

static const char *mdio_model_name(enum sg2000_mdio_model_e model)
{
  if (model == SG2000_MDIO_TRM_LEGACY)
    {
      return "trm-legacy";
    }

  return "dwmac4";
}

static uint16_t mdio_read_dwmac4(uintptr_t gmac_base, int phy_addr, int reg,
                                 bool *timedout)
{
  uint32_t cmd;
  uint32_t val;
  int timeout = 10000;

  if (timedout != NULL)
    {
      *timedout = false;
    }

  do
    {
      if (!(getreg32(gmac_base + GMAC_MDIO_ADDR) & GMAC_MDIO_BUSY))
        {
          break;
        }

      up_udelay(1);
    }
  while (--timeout > 0);

  if (timeout <= 0)
    {
      if (timedout != NULL)
        {
          *timedout = true;
        }

      return 0xffff;
    }

  putreg32(0, gmac_base + GMAC_MDIO_DATA);

  cmd = (((uint32_t)phy_addr << GMAC_MDIO_PA_SHIFT) & GMAC_MDIO_PA_MASK) |
        (((uint32_t)reg << GMAC_MDIO_RDA_SHIFT) & GMAC_MDIO_RDA_MASK) |
        GMAC_MDIO_CR_250_300M | GMAC_MDIO_GOC_READ | GMAC_MDIO_BUSY;
  putreg32(cmd, gmac_base + GMAC_MDIO_ADDR);

  timeout = 10000;
  do
    {
      val = getreg32(gmac_base + GMAC_MDIO_ADDR);
      if (!(val & GMAC_MDIO_BUSY))
        {
          return getreg32(gmac_base + GMAC_MDIO_DATA) & 0xffff;
        }

      up_udelay(1);
    }
  while (--timeout > 0);

  if (timedout != NULL)
    {
      *timedout = true;
    }

  return 0xffff;
}

static uint16_t mdio_read_trm_legacy(uintptr_t gmac_base, int phy_addr,
                                     int reg, bool *timedout)
{
  uint32_t cmd;
  uint32_t val;
  int timeout = 10000;
  uintptr_t base = gmac_base;

  if (timedout != NULL)
    {
      *timedout = false;
    }

  do
    {
      if (!(getreg32(base + LEGACY_GMAC_MDIO_ADDR) & LEGACY_GMAC_MDIO_BUSY))
        {
          break;
        }

      up_udelay(1);
    }
  while (--timeout > 0);

  if (timeout <= 0)
    {
      if (timedout != NULL)
        {
          *timedout = true;
        }

      return 0xffff;
    }

  putreg32(0, base + LEGACY_GMAC_MDIO_DATA);

  cmd = (((uint32_t)phy_addr & 0x1f) << LEGACY_GMAC_MDIO_PHY_SHIFT) |
        (((uint32_t)reg & 0x1f) << LEGACY_GMAC_MDIO_REG_SHIFT) |
        LEGACY_GMAC_MDIO_BUSY;
  putreg32(cmd, base + LEGACY_GMAC_MDIO_ADDR);

  timeout = 10000;
  do
    {
      val = getreg32(base + LEGACY_GMAC_MDIO_ADDR);
      if (!(val & LEGACY_GMAC_MDIO_BUSY))
        {
          return getreg32(base + LEGACY_GMAC_MDIO_DATA) & 0xffff;
        }

      up_udelay(1);
    }
  while (--timeout > 0);

  if (timedout != NULL)
    {
      *timedout = true;
    }

  return 0xffff;
}

static uint16_t mdio_read_status(uintptr_t gmac_base, int phy_addr, int reg,
                                 bool *timedout)
{
  if (g_mdio_model == SG2000_MDIO_TRM_LEGACY)
    {
      return mdio_read_trm_legacy(gmac_base, phy_addr, reg, timedout);
    }

  return mdio_read_dwmac4(gmac_base, phy_addr, reg, timedout);
}

static uint16_t mdio_read(uintptr_t gmac_base, int phy_addr, int reg)
{
  return mdio_read_status(gmac_base, phy_addr, reg, NULL);
}

static void mdio_diag_dump(uintptr_t gmac_base)
{
  syslog(LOG_INFO, "sg2000_eth: DWMAC4 regs cfg=0x%08" PRIX32
         " feat0=0x%08" PRIX32 " mdio_addr=0x%08" PRIX32
         " mdio_data=0x%08" PRIX32 "\n",
         getreg32(gmac_base + GMAC_CONFIG),
         getreg32(gmac_base + GMAC_HW_FEATURE0),
         getreg32(gmac_base + GMAC_MDIO_ADDR),
         getreg32(gmac_base + GMAC_MDIO_DATA));

  syslog(LOG_INFO, "sg2000_eth: legacy regs cfg=0x%08" PRIX32
         " mdio_addr=0x%08" PRIX32 " mdio_data=0x%08" PRIX32 "\n",
         getreg32(gmac_base + GMAC_CONFIG),
         getreg32(gmac_base + LEGACY_GMAC_MDIO_ADDR),
         getreg32(gmac_base + LEGACY_GMAC_MDIO_DATA));

  syslog(LOG_INFO, "sg2000_eth: EPHY top=0x%08" PRIX32
         " sel=0x%08" PRIX32 " apb_id=0x%04" PRIX32 "%04" PRIX32
         "\n",
         getreg32(SG2000_EPHY_TOP), getreg32(SG2000_EPHY_TOP + 0x4),
         getreg32(SG2000_EPHY_BASE + 0x08) & 0xffff,
         getreg32(SG2000_EPHY_BASE + 0x0c) & 0xffff);
}

static bool mdio_model_reads_phy_id(uintptr_t gmac_base,
                                    enum sg2000_mdio_model_e model,
                                    uint32_t *phy_id)
{
  bool to1;
  bool to2;
  uint16_t id1;
  uint16_t id2;
  enum sg2000_mdio_model_e saved = g_mdio_model;

  g_mdio_model = model;
  id1 = mdio_read_status(gmac_base, 0, 2, &to1);
  id2 = mdio_read_status(gmac_base, 0, 3, &to2);
  g_mdio_model = saved;

  *phy_id = ((uint32_t)id1 << 16) | id2;
  syslog(LOG_INFO, "sg2000_eth: MDIO probe %s id=0x%08" PRIX32
         " timeout=%d/%d\n", mdio_model_name(model), *phy_id,
         to1 ? 1 : 0, to2 ? 1 : 0);

  return *phy_id == CVITEK_PHY_ID;
}

static int mdio_select_model(uintptr_t gmac_base)
{
  uint32_t phy_id;

  mdio_diag_dump(gmac_base);

  if (mdio_model_reads_phy_id(gmac_base, SG2000_MDIO_DWMAC4, &phy_id))
    {
      g_mdio_model = SG2000_MDIO_DWMAC4;
      syslog(LOG_INFO, "sg2000_eth: selected MDIO model %s\n",
             mdio_model_name(g_mdio_model));
      return OK;
    }

  if (mdio_model_reads_phy_id(gmac_base, SG2000_MDIO_TRM_LEGACY, &phy_id))
    {
      g_mdio_model = SG2000_MDIO_TRM_LEGACY;
      syslog(LOG_INFO, "sg2000_eth: selected MDIO model %s\n",
             mdio_model_name(g_mdio_model));
      return OK;
    }

  syslog(LOG_ERR, "sg2000_eth: no MDIO model can read expected PHY ID\n");
  return -ENODEV;
}

static void mdio_write_dwmac4(uintptr_t gmac_base, int phy_addr, int reg,
                              uint16_t data)
{
  uint32_t cmd;
  int timeout = 10000;

  putreg32(data, gmac_base + GMAC_MDIO_DATA);
  cmd = (((uint32_t)phy_addr << GMAC_MDIO_PA_SHIFT) & GMAC_MDIO_PA_MASK) |
        (((uint32_t)reg << GMAC_MDIO_RDA_SHIFT) & GMAC_MDIO_RDA_MASK) |
        GMAC_MDIO_CR_250_300M | GMAC_MDIO_GOC_WRITE | GMAC_MDIO_BUSY;
  putreg32(cmd, gmac_base + GMAC_MDIO_ADDR);

  do
    {
      if (!(getreg32(gmac_base + GMAC_MDIO_ADDR) & GMAC_MDIO_BUSY))
        {
          break;
        }

      up_udelay(1);
    }
  while (--timeout > 0);
}

static void mdio_write_trm_legacy(uintptr_t gmac_base, int phy_addr, int reg,
                                  uint16_t data)
{
  uint32_t cmd;
  int timeout = 10000;
  uintptr_t base = gmac_base;

  putreg32(data, base + LEGACY_GMAC_MDIO_DATA);
  cmd = (((uint32_t)phy_addr & 0x1f) << LEGACY_GMAC_MDIO_PHY_SHIFT) |
        (((uint32_t)reg & 0x1f) << LEGACY_GMAC_MDIO_REG_SHIFT) |
        LEGACY_GMAC_MDIO_WRITE | LEGACY_GMAC_MDIO_BUSY;
