static uint16_t mdio_read(uintptr_t gmac_base, int phy_addr, int reg)
{
  uint32_t cmd;
  int timeout = 10000;

  do
    {
      if (!(getreg32(gmac_base + LEGACY_GMAC_MDIO_ADDR) &
