static int mdio_verify_phy(uintptr_t gmac_base)
{
  uint16_t id1 = mdio_read(gmac_base, 0, 2);
  uint16_t id2 = mdio_read(gmac_base, 0, 3);
  uint32_t phy_id = ((uint32_t)id1 << 16) | id2;

  syslog(LOG_INFO, "sg2000_eth: TRM legacy MDIO probe phy_id=0x%08"
         PRIX32 "\n", phy_id);

  if (id1 == 0xffff || id2 == 0xffff)
    {
      syslog(LOG_ERR, "sg2000_eth: TRM legacy MDIO timeout reading "
             "PHY ID\n");
      return -ENODEV;
    }

  if (phy_id != CVITEK_PHY_ID)
    {
      syslog(LOG_WARNING, "sg2000_eth: unexpected PHY ID 0x%08" PRIX32
             " (expected 0x%08" PRIX32 ")\n", phy_id,
             (uint32_t)CVITEK_PHY_ID);
    }

  return OK;
}

